mapper.select:
select t1.* from sys_menu t1


		t1.menu_type = #{menuType}


order by t1.sort asc

select t3.* from sys_role_user t1
left join sys_role_menu t2 on t1.role_id = t2.role_id
left join sys_menu t3 on t2.menu_id = t3.id
where t1.user_id = #{userId}

	and t3.menu_type = #{menuType}

order by t3.sort asc

select t3.* from sys_role_user t1 left join sys_role_menu t2 on t1.role_id = t2.role_id left join sys_menu t3 on t2.menu_id = t3.id where t1.user_id = #{userId}
and t3.menu_type = #{menuType}
and (t3.agent_purview = 1 or t3.agent_purview is null)
and (t3.ywy_purview = 1 or t3.ywy_purview is null)
order by t3.sort asc
